function splitCols(body){
  var res=[], depth=0, cur='';
  for(var i=0;i<body.length;i++){
    var ch=body[i];
    if(ch==='(') depth++;
    else if(ch===')') depth--;
    if(ch===',' && depth===0){ res.push(cur); cur=''; }
    else cur+=ch;
  }
  if(cur.trim()) res.push(cur);
  return res;
}
function parseTables(sql){
  var tables=[], re=/create\s+table\s+(?:if\s+not\s+exists\s+)?[`"]?([A-Za-z0-9_]+)[`"]?\s*\(/gi, m;
  while((m=re.exec(sql))){
    var name=m[1];
    var start=m.index + m[0].length - 1; // position of the opening '('
    var depth=1, i=start+1, body='';
    for(; i<sql.length; i++){
      var ch=sql[i];
      if(ch==='(') depth++;
      else if(ch===')'){ depth--; if(depth===0) break; }
      body+=ch;
    }
    var fields=[], fks=[];
    splitCols(body).forEach(function(c){
      var cm=c.trim().match(/^([A-Za-z0-9_]+)\s+([A-Za-z0-9_\(\)]+)/i);
      if(cm) fields.push({name:cm[1], type:cm[2]});
    });
    body.replace(/foreign\s+key\s*\(([^)]+)\)\s*references\s+[`"]?([A-Za-z0-9_]+)[`"]?\s*\(([^)]+)\)/gi,
      function(_,a,b,c){ fks.push({from:a.trim(), to:b, toCol:c.trim()}); return ''; });
    tables.push({name:name, fields:fields, fks:fks});
  }
  return tables;
}
function toMermaid(sql){
  var tables=parseTables(sql), lines=['erDiagram'];
  tables.forEach(function(t){
    lines.push('  '+t.name+' {');
    t.fields.forEach(function(f){ lines.push('    '+f.type+' '+f.name); });
    lines.push('  }');
  });
  tables.forEach(function(t){
    t.fks.forEach(function(fk){ lines.push('  '+t.name+' ||--o{ '+fk.to+' : "'+fk.from+'"'); });
  });
  return {code:lines.join('\n'), tableCount:tables.length};
}
var EXPORTS={splitCols:splitCols, parseTables:parseTables, toMermaid:toMermaid};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SqlToErForgePure = EXPORTS; }
